import { formatPythonStringLiteral } from './pythonRepr.mjs'

const PYTHON_INT_PATTERN = /^[+-]?\d(?:_?\d)*$/
const NEGATIVE_INT_TOKEN_PATTERN = /^-\d(?:_?\d)*$/

function toBigInt(rawValue) {
  const text = String(rawValue)
  const isNegative = text.startsWith('-')
  const unsignedDigits = text.replace(/^[+-]/, '').replace(/_/g, '')
  const parsedValue = BigInt(unsignedDigits)

  return isNegative ? -parsedValue : parsedValue
}

export function isNegativeIntegerToken(token) {
  return NEGATIVE_INT_TOKEN_PATTERN.test(String(token))
}

export function parsePythonInt(rawValue) {
  const text = String(rawValue)

  if (!PYTHON_INT_PATTERN.test(text)) {
    return {
      ok: false,
      message: `invalid int value: ${formatPythonStringLiteral(text)}`,
    }
  }

  return {
    ok: true,
    value: toBigInt(text),
  }
}

